   if(plans.isEmpty&&old.isNotEmpty){final map=<String,WorkoutPlan>{}; for(final w in old.map(Workout.fromJson)){final p=map.putIfAbsent(w.name,()=>WorkoutPlan(id:w.name.hashCode.toString(),name:w.name,weekdays:[],dayExercises:{})); if(!p.weekdays.contains(w.weekday))p.weekdays.add(w.weekday); p.dayExercises['${w.weekday}']=w.exercises; } plans=map.values.toList(); await _save();}
   custom=rc.map((e)=>[(e['name']??'').toString(),(e['muscle']??'Outros').toString()]).where((e)=>e[0].isNotEmpty).toList();if(mounted)setState((){});}
