 List<List<String>> get library{final all=<List<String>>[...defaultExercises,...custom];final seen=<String>{};all.removeWhere((e)=>!seen.add('${e[1]}::${e[0].toLowerCase()}'));all.sort((a,b){int ai=muscleOrder.indexOf(a[1]),bi=muscleOrder.indexOf(b[1]);ai=ai<0?999:ai;bi=bi<0?999:bi;return ai==bi?a[0].toLowerCase().compareTo(b[0].toLowerCase()):ai.compareTo(bi);});return all;}
