   if(ok!=true||name.text.trim().isEmpty)return;final cleanDays=selected.toList()..sort();final p=existing??WorkoutPlan(id:DateTime.now().microsecondsSinceEpoch.toString(),name:name.text.trim(),weekdays:cleanDays,dayExercises:{});p.name=name.text.trim();p.weekdays=cleanDays;p.dayExercises=dayExercises;plans.removeWhere((x)=>x.id==p.id);plans.add(p);await _save();if(mounted)setState((){});}
