   if(ok==true&&selected!=null){final e=library.firstWhere((x)=>x[0]==selected);dayExercises.putIfAbsent('$day',()=>[]).add(Exercise(id:DateTime.now().microsecondsSinceEpoch.toString(),name:e[0],muscle:e[1],sets:sets,reps:reps));ss((){});}}
 Future<void> _addCustomExercise()async{final n=TextEditingController();String muscle='Peito';final ok=await showDialog<bool>(context:context,builder:(c)=>StatefulBuilder(builder:(c,ss)=>AlertDialog(title:const Text('Novo exercício'),content:Column(mainAxisSize:MainAxisSize.min,children:[TextField(controller:n,decoration:const InputDecoration(labelText:'Nome')),DropdownButtonFormField<String>(initialValue:muscle,items:muscleOrder.map((m)=>DropdownMenuItem(value:m,child:Text(m))).toList(),onChanged:(v){if(v!=null)ss(()=>muscle=v);},decoration:const InputDecoration(labelText:'Músculo'))]),actions:[TextButton(onPressed:()=>Navigator.pop(c),child:const Text('Cancelar')),FilledButton(onPressed:()=>Navigator.pop(c,true),child:const Text('Salvar'))])));if(ok==true&&n.text.trim().isNotEmpty){custom.add([n.text.trim(),muscle]);await StorageService.write('exercise_library',custom.map((e)=>{'name':e[0],'muscle':e[1]}).toList());if(mounted)setState((){});}}
 Future<void> _start(WorkoutPlan p,int day)async{final exercises=p.exercisesFor(day).map((e)=>e.copy()).toList();if(exercises.isEmpty){if(mounted)ScaffoldMessenger.of(context).showSnackBar(const SnackBar(content:Text('Adicione exercícios para este dia primeiro.')));return;}await Navigator.push(context,MaterialPageRoute(builder:(_)=>WorkoutPlayer(name:p.name,day:day,exercises:exercises,onSave:()async{await StorageService.write('workout_sessions',[]); })));}
 @override Widget build(BuildContext context){final today=DateTime.now().weekday;final todays=plans.where((p)=>p.weekdays.contains(today)).toList();return SafeArea(child:ListView(padding:const EdgeInsets.fromLTRB(16,12,16,28),children:[Row(children:[Expanded(child:Column(crossAxisAlignment:CrossAxisAlignment.start,children:[Text('Academia',style:Theme.of(context).textTheme.headlineMedium?.copyWith(fontWeight:FontWeight.bold)),Text('${plans.length} treino(s) configurado(s)',style:Theme.of(context).textTheme.bodyMedium)])),FilledButton.icon(onPressed:()=>_createPlan(),icon:const Icon(Icons.add),label:const Text('Criar treino'))]),const SizedBox(height:18),if(todays.isNotEmpty)AppCard(child:Column(crossAxisAlignment:CrossAxisAlignment.start,children:[Text('Treino de hoje',style:Theme.of(context).textTheme.titleLarge?.copyWith(fontWeight:FontWeight.bold)),const SizedBox(height:8),...todays.map((p)=>ListTile(contentPadding:EdgeInsets.zero,leading:const CircleAvatar(child:Icon(Icons.play_arrow)),title:Text(p.name),subtitle:Text('${p.exercisesFor(today).length} exercícios'),trailing:FilledButton(onPressed:()=>_start(p,today),child:const Text('Iniciar')))])),if(plans.isEmpty)AppCard(child:Column(children:[const Icon(Icons.fitness_center,size:42),const SizedBox(height:8),const Text('Crie sua primeira divisão de treino.',style:TextStyle(fontWeight:FontWeight.bold)),const SizedBox(height:4),const Text('Um treino pode ter vários dias e cada dia pode ter seus próprios exercícios.')])),...plans.map((p)=>AppCard(child:Column(crossAxisAlignment:CrossAxisAlignment.start,children:[Row(children:[const Icon(Icons.fitness_center),const SizedBox(width:10),Expanded(child:Text(p.name,style:Theme.of(context).textTheme.titleLarge?.copyWith(fontWeight:FontWeight.bold))),PopupMenuButton<String>(onSelected:(v){if(v=='edit')_createPlan(existing:p);if(v=='delete'){setState(()=>plans.remove(p));_save();}},itemBuilder:(_)=>const[PopupMenuItem(value:'edit',child:Text('Editar treino')),PopupMenuItem(